-- GENERATED by `python3 -m analytics render evidence` (analytics/specs/ceo_weekly_pulse.yml#channel_performance; inputs sha256 7e42e095b5fc0298). Do not edit by hand.
WITH cur AS (
  SELECT
    j_channels.channel_name AS channel_name,
    COUNT(DISTINCT m.order_id) AS active_orders_count,
    SUM(m.net_revenue) AS net_sales
  FROM main_marts.fact_orders AS m
  LEFT JOIN main_marts.dim_channels AS j_channels ON m.channel_key = j_channels.channel_key
  WHERE m.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST(CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) AS TIMESTAMP))
    AND m.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST(((CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1) + 1) AS TIMESTAMP))
    AND m.scope_sales
    AND m.is_active_order
  GROUP BY 1
),
cmp AS (
  SELECT
    j_channels.channel_name AS channel_name,
    COUNT(DISTINCT m.order_id) AS active_orders_count,
    SUM(m.net_revenue) AS net_sales
  FROM main_marts.fact_orders AS m
  LEFT JOIN main_marts.dim_channels AS j_channels ON m.channel_key = j_channels.channel_key
  WHERE m.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST((CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) - 7) AS TIMESTAMP))
    AND m.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST(CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) AS TIMESTAMP))
    AND m.scope_sales
    AND m.is_active_order
  GROUP BY 1
)
SELECT
  COALESCE(cur.channel_name, cmp.channel_name) AS channel_name,
  COALESCE(cur.active_orders_count, 0) AS active_orders_count,
  COALESCE(cur.net_sales, 0) AS net_sales,
  COALESCE(cmp.active_orders_count, 0) AS active_orders_count__cmp,
  COALESCE(cmp.net_sales, 0) AS net_sales__cmp,
  CASE WHEN COALESCE(cmp.net_sales, 0) = 0 THEN NULL ELSE (COALESCE(cur.net_sales, 0) - cmp.net_sales) * 100.0 / cmp.net_sales END AS net_sales__pct_change
FROM cur FULL OUTER JOIN cmp ON cur.channel_name = cmp.channel_name
ORDER BY COALESCE(cur.net_sales, 0) DESC, 1
